CREATE TABLE IF NOT EXISTS equipment(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(80) UNIQUE, name VARCHAR(150), system_name VARCHAR(80), area VARCHAR(80), skill VARCHAR(80), criticality INT, affects_flights BOOLEAN, status VARCHAR(30) DEFAULT '正常');
CREATE TABLE IF NOT EXISTS technician(id BIGINT PRIMARY KEY, name VARCHAR(80), skills VARCHAR(200), area VARCHAR(80), capacity INT, active BOOLEAN);
CREATE TABLE IF NOT EXISTS inspection(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_key VARCHAR(100) UNIQUE NOT NULL, equipment_id BIGINT REFERENCES equipment(id), abnormal BOOLEAN, note VARCHAR(2000), created_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS outbox(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, inspection_id BIGINT UNIQUE REFERENCES inspection(id), state VARCHAR(30), attempts INT DEFAULT 0, last_error VARCHAR(500), created_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS work_order(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, inspection_id BIGINT UNIQUE REFERENCES inspection(id), equipment_id BIGINT REFERENCES equipment(id), priority VARCHAR(10), status VARCHAR(30), technician_id BIGINT REFERENCES technician(id), opened_at TIMESTAMP, repaired_at TIMESTAMP, accepted_at TIMESTAMP, repair_note VARCHAR(2000), acceptance_note VARCHAR(2000));
CREATE TABLE IF NOT EXISTS notification(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT REFERENCES work_order(id), recipient VARCHAR(80), message VARCHAR(1000), created_at TIMESTAMP, is_read BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, action VARCHAR(80), detail VARCHAR(2000), created_at TIMESTAMP);
